 $('#agenda').innerHTML=pf.agenda.length?pf.agenda.map(a=>`<div class="agrow ${a.overdue?'overdue':''}"><time>${dt(a.date)}</time><span class="tag ${a.kind}">${a.kind}</span><span>${esc(a.label)}</span></div>`).join(''):'<div class="empty"><p>Nada agendado: as datas vêm dos pedidos (caixa, entrega, revisão do Alvo 3) e dos meses de caixa dos produtores.</p></div>'
