 $('#attention').innerHTML=pf.attention.length?pf.attention.map(a=>`<div class="srow"><b>${esc(a.producerName)}</b><span>${esc(a.label)}: ${a.fixedPercent}% fixado (faixa ${a.band[0]}–${a.band[1]}%) • ${int(a.openSc)} sc em aberto</span><button class="mini" type="button" data-open-producer="${a.producerId}">ficha</button></div>`).join(''):'<div class="empty"><p>Nenhum produtor abaixo do ritmo de proteção para a fase atual.</p></div>'
