function sparkline(series,w=320,h=72){
 if(!series||series.length<2)return '<p class="meta">Registre ao menos duas cotações para ver a tendência.</p>'
 const xs=series.map(p=>new Date(p.observedAt).getTime());const ys=series.map(p=>p.price)
 const x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);const pad=8
 const X=t=>pad+(x1===x0?0:(t-x0)/(x1-x0))*(w-pad*2-56);const Y=v=>h-pad-(y1===y0?.5:(v-y0)/(y1-y0))*(h-pad*2)
 const d=series.map((p,i)=>`${i?'L':'M'}${X(xs[i]).toFixed(1)},${Y(ys[i]).toFixed(1)}`).join(' ')
 const last=series[series.length-1]
 return `<svg class="spark" viewBox="0 0 ${w} ${h}" role="img" aria-label="Tendência de ${series.length} cotações">${[y0,y1].map(v=>`<line x1="${pad}" x2="${w-56}" y1="${Y(v)}" y2="${Y(v)}" class="grid"/>`).join('')}<path d="${d}" class="line"/>${series.map((p,i)=>`<g class="pt"><circle cx="${X(xs[i])}" cy="${Y(ys[i])}" r="4"/><circle cx="${X(xs[i])}" cy="${Y(ys[i])}" r="12" class="hit"><title>${money(p.price)} • ${esc(p.sourceName)} • ${dt(p.observedAt)}</title></circle></g>`).join('')}<text x="${X(xs[xs.length-1])+8}" y="${Y(last.price)+4}" class="lbl">${money(last.price)}</text></svg>`
}
function renderTrend(){
 const pf=state.portfolio;const el=$('#trend');if(!pf||!el)return
 el.innerHTML=pf.commodities.filter(c=>c.series.length).map(c=>`<div class="trendrow"><header><b>${esc(c.label)}</b><small>${c.series.length} cotações locais • ${c.changePercent!=null?`${c.changePercent>=0?'▲':'▼'} ${Math.abs(c.changePercent).toFixed(1).replace('.',',')}%`:''}</small></header>${sparkline(c.series)}</div>`).join('')
}
