 $('#stAlerts').innerHTML=st.alerts.length?`<div class="alertlist">${st.alerts.slice(0,12).map(a=>`<p class="note ${a.level==='fora'?'danger':a.level==='atencao'?'warn':'gap'}"><b>${a.level==='fora'?'Crítico':a.level==='atencao'?'Atenção':'Rotina'}</b><span>${esc(a.message)}</span></p>`).join('')}</div>`:''
