 const ps=$('#receiptForm select[name=producerId]');const pv=ps.value;ps.innerHTML='<option value="">—</option>'+(state.producers||[]).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');if(pv)ps.value=pv
 for(const fid of ['receiptsReportForm','storageReportForm']){const us=$(`#${fid} select[name=unitId]`);const uv=us.value;us.innerHTML='<option value="">Todas</option>'+units.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('');if(uv)us.value=uv;const cs=$(`#${fid} select[name=commodity]`);if(cs.options.length<=1)cs.innerHTML='<option value="">Todos</option>'+state.catalog.commodities.map(c=>`<option value="${c.value}">${esc(c.label)}</option>`).join('')}
 if(!$('#unitGoals').children.length)$('#unitGoals').innerHTML=state.catalog.commodities.map(c=>`<label>${esc(c.label)} (t)<input name="goal_${c.value}" type="number" min="0" step="1"></label>`).join('')
 // standards
 const std=st.standards;const labels=st.parameterLabels||{}
 $('#standardsBody').innerHTML=`<table class="stdtable"><thead><tr><th>Grão</th><th>Parâmetro</th><th>Máximo</th><th>Mínimo</th><th>Ideal</th></tr></thead><tbody>${Object.entries(std).map(([c,params])=>Object.entries(params).map(([k,r],i)=>`<tr>${i===0?`<td class="c" rowspan="${Object.keys(params).length}">${esc(state.catalog.commodities.find(x=>x.value===c)?.label||c)}</td>`:''}<td>${esc(r.label||labels[k]||k)}</td><td><input name="${c}.${k}.max" type="number" step="0.1" value="${r.max??''}" ${write?'':'disabled'}></td><td><input name="${c}.${k}.min" type="number" step="0.1" value="${r.min??''}" ${write?'':'disabled'}></td><td><input name="${c}.${k}.ideal" type="number" step="0.1" value="${r.ideal??''}" ${write?'':'disabled'}></td></tr>`).join('')).join('')}</tbody></table>`
 // recent lists
 const rc=st.receipts||[];$('#stReceipts').innerHTML=rc.length?`<table class="cmptable"><thead><tr><th>Data</th><th>Unidade</th><th>Grão</th><th>t</th><th>Cargas</th><th>Umid.</th><th>Produtor</th><th></th></tr></thead><tbody>${rc.slice(0,25).map(r=>`<tr><td>${dt(r.date)}</td><td>${esc(units.find(u=>u.id===r.unitId)?.name||'—')}</td><td>${esc(state.catalog.commodities.find(x=>x.value===r.commodity)?.label||r.commodity)}</td><td>${r.quantityT.toLocaleString('pt-BR')}</td><td>${r.loads??'—'}</td><td>${r.params?.moisture!=null?String(r.params.moisture).replace('.',','):'—'}</td><td>${esc(r.producerName||'—')}</td><td>${write?`<button class="mini" data-del-receipt="${r.id}">×</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<p class="meta">Nenhum recebimento registrado.</p>'
 const rd=st.readings||[];$('#stReadings').innerHTML=rd.length?`<table class="cmptable"><thead><tr><th>Leitura</th><th>Unidade</th><th>Grão</th><th>t</th><th>Umid.</th><th>Temp.</th><th>Imp.</th><th></th></tr></thead><tbody>${rd.slice(0,25).map(r=>`<tr><td>${dt(r.date)}${r.silo?' • '+esc(r.silo):''}</td><td>${esc(units.find(u=>u.id===r.unitId)?.name||'—')}</td><td>${esc(state.catalog.commodities.find(x=>x.value===r.commodity)?.label||r.commodity)}</td><td>${r.quantityT.toLocaleString('pt-BR')}</td><td>${r.params?.moisture!=null?String(r.params.moisture).replace('.',','):'—'}</td><td>${r.params?.temperature!=null?String(r.params.temperature).replace('.',','):'—'}</td><td>${r.params?.impurities!=null?String(r.params.impurities).replace('.',','):'—'}</td><td>${write?`<button class="mini" data-del-reading="${r.id}">×</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<p class="meta">Nenhuma leitura registrada.</p>'
