async function submitOffer(persist){
 const f=$('#offerForm');$('#offerError').hidden=true;const btns=f.querySelectorAll('button');btns.forEach(b=>b.disabled=true)
 try{const r=await api(persist?'/api/offers':'/api/offers/preview',{method:'POST',body:JSON.stringify(formData(f))});const o=persist?r.offer.offer:r.offer;$('#offerResult').innerHTML=offerHtml(o);if(persist){status('Oferta registrada.');await load()}$('#offerResult').scrollIntoView({behavior:'smooth',block:'start'})}
 catch(e){$('#offerError').textContent=e.message;$('#offerError').hidden=false}finally{btns.forEach(b=>b.disabled=false)}
}
