function renderDestinations(list){$('#destinations').innerHTML=list.map((d,i)=>`<div class="destrow"><input name="dname" value="${esc(d.name)}" placeholder="nome"><input name="dkm" type="number" min="0" value="${d.km}"><select name="dkind"><option value="unit" ${d.kind==='unit'?'selected':''}>unidade</option><option value="port" ${d.kind==='port'?'selected':''}>porto</option><option value="buyer" ${d.kind==='buyer'?'selected':''}>comprador</option></select><button class="mini" type="button" data-rm="${i}">×</button><input type="hidden" name="did" value="${esc(d.id||'')}"></div>`).join('');$$('#destinations [data-rm]').forEach(b=>b.addEventListener('click',()=>{const rows=readDestinations();rows.splice(Number(b.dataset.rm),1);renderDestinations(rows)}))}
