 renderAskingHistory()
 {const ps=$('#offersReportForm select[name=producerId]');const pv=ps.value;ps.innerHTML='<option value="">Todos</option>'+(state.producers||[]).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');if(pv)ps.value=pv}
